using MarketSphere.Domain.Entities.CRM;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace MarketSphere.Infrastructure.Persistence.Configurations.CRM;
public sealed class LeadConfiguration : IEntityTypeConfiguration<Lead> { public void Configure(EntityTypeBuilder<Lead> b) { b.ToTable("Leads", t => t.HasCheckConstraint("CK_Leads_CurrentScore", "[CurrentScore] >= 0 AND [CurrentScore] <= 100")); b.HasKey(x => x.LeadID); b.Property(x => x.LeadCode).HasMaxLength(30).IsRequired(); b.Property(x => x.LeadName).HasMaxLength(150).IsRequired(); b.Property(x => x.BusinessName).HasMaxLength(200); b.Property(x => x.Phone).HasMaxLength(30); b.Property(x => x.Email).HasMaxLength(256); b.Property(x => x.ProductInterest).HasMaxLength(500); b.Property(x => x.EstimatedValue).HasPrecision(18, 2); b.Property(x => x.LostReason).HasMaxLength(500); b.HasIndex(x => x.LeadCode).IsUnique(); b.HasIndex(x => x.Phone); b.HasIndex(x => x.Email); b.HasIndex(x => new { x.Status, x.AssignedEmployeeID, x.NextFollowUpAt }); b.HasOne(x => x.AssignedEmployee).WithMany().HasForeignKey(x => x.AssignedEmployeeID).OnDelete(DeleteBehavior.Restrict); b.HasOne(x => x.Region).WithMany().HasForeignKey(x => x.RegionID).OnDelete(DeleteBehavior.Restrict); b.HasOne(x => x.ConvertedClient).WithMany().HasForeignKey(x => x.ConvertedClientID).OnDelete(DeleteBehavior.Restrict); b.HasOne(x => x.SourceCampaign).WithMany().HasForeignKey(x => x.SourceCampaignID).OnDelete(DeleteBehavior.Restrict); } }
